arguments.new_string:
        i += 2
    return cur


class Auto(object):
    """Auto-detect whether to iterate over the target or treat it as a single value.

    If the target is iterable (but not a string), Auto will iterate over it.
    Otherwise, it will treat the target as a single value.

    This is useful when you want to handle both single values and collections
    uniformly in your spec.

    >>> target = [1, 2, 3]
    >>> glom(target, Auto)
    [1, 2, 3]
    >>> target = 42
    >>> glom(target, Auto)
    42

    """
    def __repr__(self):
        return 'Auto()'

    def glomit(self, target, scope):
        from boltons.iterutils import is_iterable
        if is_iterable(target) and not isinstance(target, str):
            return list(scope[TargetRegistry].get_handler('iterate', target)(target))
        return target


class Fill(object):
    """Fill missing keys/values with a default value.

    Fill takes a mapping (like a dict) and fills any missing keys
    specified in *defaults* with their corresponding values.

    Args:
       defaults: A mapping of keys to default values to fill in.

    >>> target = {'a': 1}
    >>> glom(target, Fill({'a': 0, 'b': 2}))
    {'a': 1, 'b': 2}

    """
    def __init__(self, defaults):
        self.defaults = defaults

    def __repr__(self):
        return 'Fill(%r)' % (self.defaults,)

    def glomit(self, target, scope):
        if not hasattr(target, 'keys'):
            raise TypeError('Fill expects a mapping, got %r' % type(target).__name__)
        result = dict(target)
        for key, val in self.defaults.items():
            if key not in result:
                result[key] = scope[glom](target, val, scope) if callable(val) else val
        return result


class Iter(object):
    """Force iteration over the target regardless of its type.

    Unlike Auto, which checks if the target is iterable, Iter always
    attempts to iterate. This is useful when you know the target should
    be iterated even if it might not normally be considered iterable.

    Args:
       spec: An optional subspec to apply to each item during iteration.

    >>> target = 'abc'
    >>> glom(target, Iter)
    ['a', 'b', 'c']

    """
    def __init__(self, spec=None):
        self.spec = spec

    def __repr__(self):
        if self.spec is None:
            return 'Iter()'
        return 'Iter(%r)' % (self.spec,)

    def glomit(self, target, scope):
        try:
            iterator = iter(target)
        except TypeError as e:
            raise TypeError('failed to iterate on instance of type %r at %r (got %r)'
                            % (type(target).__name__, Path(*scope[Path]), e))
        ret = []
        for i, t in enumerate(iterator):
            if self.spec is not None:
                val = scope[glom](t, self.spec, scope.new_child({Path: scope[Path] + [i]}))
            else:
                val = t
            if val is SKIP:
                continue
            if val is STOP:
                break
            ret.append(val)
        return ret


class Let(object):
    """Bind variables in the scope for use in subsequent specs.

    Let allows you to define temporary variables within a spec that can
    be referenced by other specs using S (scope access).

    Args:
       bindings: A mapping of variable names to values or specs.

    >>> target = {'a': 1, 'b': 2}
    >>> glom(target, Let({'sum': lambda t: t['a'] + t['b']}), 'sum')
    3

    """
    def __init__(self, bindings):
        self.bindings = bindings

    def __repr__(self):
        return 'Let(%r)' % (self.bindings,)

    def glomit(self, target, scope):
        new_scope = dict(scope)
        for name, val in self.bindings.items():
            if callable(val):
                new_scope[name] = val(target)
            else:
                new_scope[name] = scope[glom](target, val, scope)
        return scope[glom](target, scope.get('_spec', target), new_scope)


